using System;using System.Linq;using WorldGenesis.Simulation;
#if UNITY_5_3_OR_NEWER
using NUnit.Framework;
#endif
namespace WorldGenesis.Tests {
 public static class BuildingPlacementScenarios {
  static void Need(bool ok,string why){FaunaBalanceScenarios.Need(ok,why);}static object Call(SimulationEngine e,string name,params object[] args){return FaunaBalanceScenarios.Call(e,name,args);}
  static SimulationEngine Town(){var e=FaunaBalanceScenarios.Flat();e.Spawn(SpeciesType.Human,12,12,3);foreach(var t in TechnologyCatalog.All)e.World.Settlements[0].UnlockedTechnologies.Add(t.Id);e.World.Settlements[0].Wood=500;var hall=e.World.Buildings.Find(b=>b.Type==BuildingType.Hall);hall.Inventory[(int)ItemType.RawStone]=100;return e;}
  public static void EveryBuildingTypeRejectsWaterFordAndBridgeFoundations(){var e=Town();int x=22,y=20,cell=e.World.Index(x,y);for(int variant=0;variant<4;variant++){var t=e.World.Cells[cell];t.Terrain=variant==0?TerrainType.DeepWater:variant==3?TerrainType.Grass:TerrainType.ShallowWater;t.WaterKind=WaterKind.River;t.WaterDepth=variant==0?2:variant==3?0:.2f;e.World.Cells[cell]=t;var infra=e.World.Infrastructure[cell];infra.BridgeLevel=(byte)(variant>=2?1:0);infra.BridgeOwnerId=variant>=2?e.World.Settlements[0].Id:0;e.World.Infrastructure[cell]=infra;for(int type=0;type<=26;type++)Need(!PlacementRules.CanPlaceBuilding(e.World,(BuildingType)type,x,y),"water/bridge accepted type "+type+" variant "+variant);} }
  public static void RejectedConstructionSpendsNoResourcesIdsOrExistingBridge(){var e=Town();var s=e.World.Settlements[0];int c=e.World.Index(22,20);var t=e.World.Cells[c];t.Terrain=TerrainType.ShallowWater;t.WaterDepth=.2f;t.WaterKind=WaterKind.River;e.World.Cells[c]=t;var bridge=e.World.Infrastructure[c];bridge.BridgeLevel=1;bridge.BridgeOwnerId=s.Id;e.World.Infrastructure[c]=bridge;float wood=s.Wood;int id=e.World.NextId;for(int type=7;type<=26;type++)Need(!e.TryBuildInfrastructure(s.Id,(BuildingType)type,22,20),"wet build accepted");Need(s.Wood==wood&&e.World.NextId==id&&e.World.Infrastructure[c].BridgeLevel==1,"failed placement damaged property");Need(Call(e,"AddBuilding",s,22,20,BuildingType.Farm)==null,"central builder allowed flooded farm");Need(e.World.NextId==id,"failed central builder spent ID");FaunaBalanceScenarios.Valid(e);}
  public static void CoastalPortFoundationStaysOnLandWhileBerthUsesWater(){var e=Town();var s=e.World.Settlements[0];for(int y=0;y<48;y++)for(int x=0;x<6;x++){var t=e.World.Cells[e.World.Index(x,y)];t.Terrain=TerrainType.DeepWater;t.WaterDepth=2;t.WaterKind=WaterKind.Ocean;e.World.Cells[e.World.Index(x,y)]=t;}Need(e.TryBuildInfrastructure(s.Id,BuildingType.Port,6,12),"valid dry coast rejected");var p=e.World.Buildings.Find(b=>b.Type==BuildingType.Port);Need(PlacementRules.IsDryGround(e.World,p.X,p.Y)&&MaritimeCatalog.IsWater(e.World,p.BerthCell,ShipKind.Transport),"port not dry or berth not wet");Need(!e.TryBuildInfrastructure(s.Id,BuildingType.Port,5,12),"port built on sea");FaunaBalanceScenarios.Valid(e);}
  public static void FoundingAndAutomaticSiteSelectionNeverChooseBridgeOrFord(){var e=FaunaBalanceScenarios.Flat();for(int i=0;i<e.World.Cells.Length;i++){var t=e.World.Cells[i];t.Terrain=TerrainType.ShallowWater;t.WaterDepth=.2f;t.WaterKind=WaterKind.River;e.World.Cells[i]=t;}e.Spawn(SpeciesType.Human,20,20,4);Need(e.World.Buildings.Count==0&&e.World.Settlements.Count==0,"founded settlement entirely on ford");var dry=e.World.Cells[e.World.Index(20,20)];dry.Terrain=TerrainType.Grass;dry.WaterDepth=0;dry.WaterKind=WaterKind.None;e.World.Cells[e.World.Index(20,20)]=dry;e.World.NavigationRevision++;e.Spawn(SpeciesType.Human,20,20,2);Need(e.World.Buildings.Count==1&&e.World.Buildings.All(b=>PlacementRules.IsDryGround(e.World,b.X,b.Y)),"automatic field chose ford");FaunaBalanceScenarios.Valid(e);}
  public static void TemporaryFloodPreservesFieldAndPausesGrowthUntilWaterRecedes(){var e=Town();BuildingData farm=e.World.Buildings.Find(b=>b.Type==BuildingType.Farm);farm.CropGrowth=.2f;farm.HarvestReady=0;int cell=e.World.Index(farm.X,farm.Y);TileData dry=e.World.Cells[cell],wet=dry;wet.Terrain=TerrainType.ShallowWater;wet.WaterDepth=.2f;wet.WaterKind=WaterKind.River;wet.ChannelWidth=1;wet.CurrentStrength=.1f;wet.River=false;e.World.Cells[cell]=wet;e.World.FloodCells.Add(new FloodCellData{Cell=cell,ExpiresTick=10,OriginalTerrain=dry.Terrain,OriginalWaterKind=dry.WaterKind,OriginalDepth=dry.WaterDepth,OriginalCurrent=dry.CurrentStrength,OriginalHeight=dry.Height,OriginalChannelWidth=dry.ChannelWidth,OriginalRiver=dry.River,AppliedDepth=.2f,AppliedCurrent=.1f,WaterSurface=dry.Height+.2f});Call(e,"DestroyInvalidBuildings");Call(e,"UpdateAgriculture");Need(e.World.GetBuilding(farm.Id)!=null&&farm.CropGrowth==.2f,"temporary flood removed field or kept growing");e.World.Tick=10;Call(e,"RecedeFloods");Call(e,"UpdateAgriculture");Need(PlacementRules.IsDryGround(e.World,farm.X,farm.Y)&&farm.CropGrowth>.2f,"field did not resume after recession");FaunaBalanceScenarios.Valid(e);}
  public static void TerrainChangeEvacuatesExistingHouseThroughOrdinaryDestruction(){var e=Town();var s=e.World.Settlements[0];var b=(BuildingData)Call(e,"AddBuilding",s,22,20,BuildingType.House);var u=e.World.Units[0];u.InsideBuildingId=b.Id;u.X=22.5f;u.Y=20.5f;u.Task=UnitTask.Rest;u.CarriedFood=1;u.Path.Clear();u.PathCursor=0;b.Inventory[(int)ItemType.Plank]=2;e.Paint(TerrainType.ShallowWater,22,20,0);Need(e.World.GetBuilding(b.Id)==null&&u.InsideBuildingId==0&&u.CarriedFood==1,"terrain change failed evacuation/cargo");Need(e.World.LostResources[(int)ItemType.Plank]+e.World.GroundStocks.Where(g=>g.Item==ItemType.Plank).Sum(g=>g.Amount)>=2,"stored goods vanished without loss accounting");FaunaBalanceScenarios.Valid(e);}
 }
#if UNITY_5_3_OR_NEWER
 public class BuildingPlacementTests {
 [TestCase("EveryBuildingTypeRejectsWaterFordAndBridgeFoundations")][TestCase("RejectedConstructionSpendsNoResourcesIdsOrExistingBridge")][TestCase("CoastalPortFoundationStaysOnLandWhileBerthUsesWater")][TestCase("FoundingAndAutomaticSiteSelectionNeverChooseBridgeOrFord")][TestCase("TerrainChangeEvacuatesExistingHouseThroughOrdinaryDestruction")][TestCase("TemporaryFloodPreservesFieldAndPausesGrowthUntilWaterRecedes")]
 public void Scenario(string name){typeof(BuildingPlacementScenarios).GetMethod(name).Invoke(null,null);}}
#endif
}
